//
//  PlanView.swift
//  Dialed
//
//  The adaptive daily schedule. Loaded as the new "Plan" tab. Pulls from
//  DailyPlan (generated by PlanGenerator) — falls back to an on-demand
//  generation if today's plan hasn't been created yet.
//
//  Visual structure (Neka):
//    • Header: big "Plan" title + regenerate button
//    • Week strip (7 days) — pill cells, tap to pivot
//    • Stats row: wake / sleep target / recovery used for anchoring
//    • Timeline: blocks grouped by day period (morning / midday / afternoon /
//      evening / night) — each block is a light card with pillar accent,
//      status-aware styling, time, title, completion control
//

import SwiftUI
import SwiftData

struct PlanView: View {
    @Environment(\.modelContext) private var modelContext
    @StateObject private var viewModel = PlanViewModel()

    var body: some View {
        NavigationStack {
            ScrollView {
                VStack(alignment: .leading, spacing: 20) {
                    header
                    weekStrip
                    anchorRow
                        .nekaLoading(!viewModel.hasLoaded)
                    timeline
                }
                .animation(.easeOut(duration: 0.3), value: viewModel.hasLoaded)
                .padding(.horizontal, 16)
                .padding(.bottom, 48)
            }
            .scrollIndicators(.hidden)
            .nekaPageBackground()
            .nekaStatusBarScrim()
            .toolbar(.hidden, for: .navigationBar)
            .task {
                viewModel.observeNotificationActions(context: modelContext)
                await viewModel.refresh(context: modelContext)
            }
            .refreshable { await viewModel.refresh(context: modelContext) }
        }
    }

    // MARK: - Header

    private var header: some View {
        HStack(alignment: .center) {
            Text("Plan")
                .font(Neka.display(34, weight: .bold))
                .tracking(-0.8)
                .foregroundColor(Neka.ink)
            Spacer()
            regenerateButton
        }
        .padding(.top, 8)
    }

    // MARK: - Regenerate button

    private var regenerateButton: some View {
        Button {
            #if os(iOS)
            UISelectionFeedbackGenerator().selectionChanged()
            #endif
            Task { await viewModel.regenerate(context: modelContext) }
        } label: {
            Group {
                if viewModel.isGenerating {
                    ProgressView()
                        .controlSize(.small)
                        .tint(Neka.ink)
                } else {
                    Image(systemName: "arrow.triangle.2.circlepath")
                        .font(.system(size: 15, weight: .semibold))
                        .foregroundColor(Neka.ink)
                }
            }
            .frame(width: 44, height: 44)
            .background(Circle().fill(Neka.surface))
            .overlay(Circle().stroke(Neka.hairline, lineWidth: 1))
        }
        .buttonStyle(.dialedScale)
        .disabled(viewModel.isGenerating)
        .accessibilityLabel("Regenerate plan")
    }

    // MARK: - Week strip

    private var weekStrip: some View {
        ScrollView(.horizontal, showsIndicators: false) {
            HStack(spacing: 8) {
                ForEach(viewModel.weekDays, id: \.self) { date in
                    weekDayCell(for: date)
                }
            }
            .padding(.horizontal, 2)
            .padding(.vertical, 4)
        }
    }

    private func weekDayCell(for date: Date) -> some View {
        let isSelected = Calendar.current.isDate(date, inSameDayAs: viewModel.selectedDate)
        let isToday = Calendar.current.isDateInToday(date)
        let showTodayDot = isToday && !isSelected
        let dayLetter = Self.weekdayLetter(date)
        let dayNumber = Calendar.current.component(.day, from: date)

        return Button {
            #if os(iOS)
            UIImpactFeedbackGenerator(style: .light).impactOccurred()
            #endif
            _ = withAnimation(.spring(response: 0.32, dampingFraction: 0.8)) {
                Task { await viewModel.select(date: date, context: modelContext) }
            }
        } label: {
            VStack(spacing: 4) {
                Text(dayLetter)
                    .font(.system(size: 10, weight: .semibold))
                    .tracking(0.6)
                    .foregroundColor(isSelected ? Neka.onInk.opacity(0.8) : Neka.inkSecondary)

                Text("\(dayNumber)")
                    .font(.system(size: 17, weight: .semibold))
                    .monospacedDigit()
                    .foregroundColor(isSelected ? Neka.onInk : Neka.ink)

                Circle()
                    .fill(showTodayDot ? Neka.green : Color.clear)
                    .frame(width: 4, height: 4)
            }
            .frame(minWidth: 44, minHeight: 60)
            .padding(.vertical, 8)
            .padding(.horizontal, 6)
            .background(
                Capsule(style: .continuous)
                    .fill(isSelected ? Neka.ink : Neka.surface)
                    .overlay(
                        Capsule(style: .continuous)
                            .stroke(isSelected ? Color.clear : Neka.hairline, lineWidth: 1)
                    )
            )
            .animation(.spring(response: 0.32, dampingFraction: 0.8), value: isSelected)
        }
        .buttonStyle(.dialedScale)
        .accessibilityLabel("\(dayLetter), \(dayNumber)\(isToday ? ", today" : "")")
        .accessibilityAddTraits(isSelected ? .isSelected : [])
    }

    // MARK: - Anchor row (wake / sleep / recovery)

    private var anchorRow: some View {
        HStack(spacing: 10) {
            anchorTile(
                icon: "sun.max.fill",
                label: "Wake",
                value: viewModel.wakeAnchorLabel,
                tint: Neka.orange,
                fill: Neka.orangeSoft,
                wash: .peach
            )
            anchorTile(
                icon: "moon.stars.fill",
                label: "Sleep",
                value: viewModel.sleepAnchorLabel,
                tint: Neka.lavender,
                fill: Neka.lavenderSoft,
                wash: .lavender
            )
            anchorTile(
                icon: "leaf.fill",
                label: "Recovery",
                value: viewModel.recoveryLabel,
                tint: Neka.green,
                fill: Neka.greenSoft,
                wash: .mint
            )
        }
    }

    private func anchorTile(icon: String, label: String, value: String,
                            tint: Color, fill: Color, wash: Neka.Wash) -> some View {
        VStack(alignment: .leading, spacing: 8) {
            NekaIconBadge(systemName: icon, tint: tint, fill: fill, size: 30)

            Text(value)
                .font(Neka.display(18, weight: .semibold))
                .monospacedDigit()
                .foregroundColor(Neka.ink)
                .lineLimit(1)
                .minimumScaleFactor(0.7)
                .contentTransition(.numericText())

            Text(label)
                .font(Neka.caption)
                .foregroundColor(Neka.inkSecondary)
        }
        .frame(maxWidth: .infinity, alignment: .leading)
        .padding(12)
        .nekaCard(cornerRadius: 20, wash: wash)
        .accessibilityElement(children: .combine)
        .accessibilityLabel("\(label): \(value)")
    }

    // MARK: - Timeline

    private var timeline: some View {
        VStack(spacing: 20) {
            if !viewModel.hasLoaded {
                // First load (may generate the day's plan): placeholder blocks.
                VStack(spacing: 10) {
                    ForEach(0..<4, id: \.self) { _ in
                        HStack(spacing: 12) {
                            Circle().fill(Neka.skeleton).frame(width: 36, height: 36)
                            VStack(alignment: .leading, spacing: 8) {
                                NekaSkeleton(width: 150, height: 12)
                                NekaSkeleton(width: 90, height: 10)
                            }
                            Spacer(minLength: 0)
                        }
                        .padding(14)
                        .nekaShimmer()
                        .nekaCard()
                    }
                }
                .transition(.opacity)
            } else if viewModel.groupedBlocks.isEmpty {
                emptyState
            } else {
                ForEach(viewModel.groupedBlocks, id: \.title) { group in
                    periodSection(group)
                }
            }
        }
    }

    private func periodSection(_ group: PlanViewModel.DayPeriodGroup) -> some View {
        VStack(alignment: .leading, spacing: 10) {
            HStack(spacing: 6) {
                Image(systemName: group.icon)
                    .font(.system(size: 13, weight: .semibold))
                    .foregroundColor(Neka.inkSecondary)
                Text(group.title)
                    .font(.system(size: 17, weight: .semibold))
                    .foregroundColor(Neka.ink)
                Spacer()
                Text(group.timeRange)
                    .font(Neka.label)
                    .foregroundColor(Neka.inkSecondary)
            }
            .padding(.horizontal, 4)

            VStack(spacing: 10) {
                ForEach(group.blocks, id: \.id) { item in
                    PlanBlockRow(
                        item: item,
                        onToggle: { Task { await viewModel.toggle(blockID: item.id, context: modelContext) } }
                    )
                }
            }
        }
    }

    private var emptyState: some View {
        VStack(spacing: 14) {
            NekaIconBadge(systemName: "calendar.badge.plus", tint: Neka.sky, fill: Neka.skySoft, size: 56)

            Text("No plan for this day yet")
                .font(Neka.title)
                .foregroundColor(Neka.ink)

            Text("Tap regenerate to build a schedule from your weekly template.")
                .font(.system(size: 13))
                .foregroundColor(Neka.inkSecondary)
                .multilineTextAlignment(.center)
                .padding(.horizontal, 20)

            Button {
                Task { await viewModel.regenerate(context: modelContext) }
            } label: {
                Group {
                    if viewModel.isGenerating {
                        HStack(spacing: 8) {
                            ProgressView().tint(Neka.onInk).controlSize(.small)
                            Text("Generating…")
                        }
                    } else {
                        Text("Generate plan")
                    }
                }
                .font(.system(size: 14, weight: .semibold))
                .foregroundColor(Neka.onInk)
                .padding(.horizontal, 22)
                .padding(.vertical, 12)
                .background(Capsule().fill(Neka.ink))
            }
            .buttonStyle(.dialedScale)
            .disabled(viewModel.isGenerating)
            .padding(.top, 4)
            .accessibilityLabel("Generate plan from template")
        }
        .frame(maxWidth: .infinity)
        .padding(.vertical, 32)
        .padding(.horizontal, 16)
        .nekaCard(wash: .sky)
    }

    // MARK: - Helpers

    private static func weekdayLetter(_ date: Date) -> String {
        let f = DateFormatter()
        f.dateFormat = "EEE"
        return String(f.string(from: date).prefix(3)).uppercased()
    }
}

// MARK: - Pillar → Neka colors

private extension AppColors.Pillar {
    var nekaTint: Color {
        switch self {
        case .recovery:  return Neka.green
        case .readiness: return Neka.sky
        case .energy:    return Neka.orange
        case .strain:    return Neka.rose
        }
    }

    var nekaFill: Color {
        switch self {
        case .recovery:  return Neka.greenSoft
        case .readiness: return Neka.skySoft
        case .energy:    return Neka.orangeSoft
        case .strain:    return Neka.roseSoft
        }
    }
}

// MARK: - Block row

private struct PlanBlockRow: View {
    let item: PlanViewModel.BlockItem
    let onToggle: () -> Void

    private var isFinished: Bool { item.status == .done || item.status == .skipped }

    var body: some View {
        HStack(spacing: 12) {
            // Time column
            VStack(alignment: .trailing, spacing: 1) {
                Text(item.timeLabel)
                    .font(.system(size: 13, weight: .semibold))
                    .monospacedDigit()
                    .foregroundColor(Neka.ink)
                if let dur = item.durationLabel {
                    Text(dur)
                        .font(.system(size: 11, weight: .medium))
                        .foregroundColor(Neka.inkTertiary)
                }
            }
            .frame(width: 58, alignment: .trailing)

            // Pillar-tinted icon badge
            NekaIconBadge(
                systemName: item.icon,
                tint: item.pillar.nekaTint,
                fill: item.pillar.nekaFill,
                size: 38
            )
            .opacity(isFinished ? 0.55 : 1)

            // Title + subtitle
            VStack(alignment: .leading, spacing: 3) {
                Text(item.title)
                    .font(Neka.title)
                    .foregroundColor(isFinished ? Neka.inkSecondary : Neka.ink)
                    .strikethrough(isFinished, color: Neka.inkTertiary)
                    .animation(.easeInOut(duration: 0.2), value: item.status)
                if let subtitle = item.subtitle {
                    Text(subtitle)
                        .font(.system(size: 12))
                        .foregroundColor(Neka.inkSecondary)
                        .lineLimit(1)
                }
                if let skipNote = item.skipReason {
                    Text(skipNote)
                        .font(.system(size: 11, weight: .medium))
                        .foregroundColor(Neka.orange)
                        .lineLimit(2)
                }
                if let pill = statusPill {
                    NekaPill(text: pill.text, tint: pill.tint, fill: pill.fill)
                        .padding(.top, 2)
                }
            }

            Spacer(minLength: 4)

            // Completion toggle
            statusControl
        }
        .padding(.horizontal, 14)
        .padding(.vertical, 14)
        .nekaCard(cornerRadius: 22, wash: cardWash)
        .overlay(
            RoundedRectangle(cornerRadius: 22, style: .continuous)
                .stroke(cardStroke, lineWidth: item.status == .active ? 1.5 : 0)
        )
        .animation(.easeInOut(duration: 0.2), value: item.status)
        .accessibilityElement(children: .combine)
        .accessibilityLabel(accessibilityLabel)
    }

    private var accessibilityLabel: String {
        let statusWord: String
        switch item.status {
        case .done:     statusWord = "Done"
        case .skipped:  statusWord = "Skipped"
        case .active:   statusWord = "In progress"
        case .due:      statusWord = "Due now"
        case .upcoming: statusWord = "Upcoming"
        }
        return "\(item.title), \(item.timeLabel), \(statusWord)"
    }

    /// Status color: done = green, active = sky, missed/due = rose,
    /// upcoming = secondary ink, skipped = tertiary ink.
    private var statusTint: Color {
        switch item.status {
        case .done:     return Neka.green
        case .active:   return Neka.sky
        case .due:      return Neka.rose
        case .upcoming: return Neka.inkSecondary
        case .skipped:  return Neka.inkTertiary
        }
    }

    private var statusPill: (text: String, tint: Color, fill: Color)? {
        switch item.status {
        case .active:  return ("NOW", Neka.sky, Neka.skySoft)
        case .due:     return ("MISSED", Neka.rose, Neka.roseSoft)
        case .skipped: return ("SKIPPED", Neka.inkSecondary, Neka.track)
        case .done, .upcoming: return nil
        }
    }

    private var cardWash: Neka.Wash {
        switch item.status {
        case .active: return .sky
        case .due:    return .rose
        default:      return .plain
        }
    }

    private var cardStroke: Color {
        item.status == .active ? Neka.sky.opacity(0.6) : Color.clear
    }

    @ViewBuilder
    private var statusControl: some View {
        Button {
            #if os(iOS)
            UIImpactFeedbackGenerator(style: .medium).impactOccurred()
            #endif
            onToggle()
        } label: {
            statusGlyph
                .frame(width: 44, height: 44)  // touch target
                .contentShape(Rectangle())
        }
        .buttonStyle(.dialedScale)
        .accessibilityLabel(statusControlLabel)
    }

    @ViewBuilder
    private var statusGlyph: some View {
        switch item.status {
        case .done:
            Image(systemName: "checkmark.circle.fill")
                .font(.system(size: 24, weight: .semibold))
                .foregroundColor(statusTint)
        case .skipped:
            Image(systemName: "slash.circle.fill")
                .font(.system(size: 24, weight: .semibold))
                .foregroundColor(statusTint)
        case .active:
            ZStack {
                Circle()
                    .stroke(statusTint.opacity(0.6), lineWidth: 1.8)
                    .frame(width: 24, height: 24)
                Circle()
                    .fill(statusTint)
                    .frame(width: 9, height: 9)
            }
        case .due:
            Circle()
                .stroke(statusTint, lineWidth: 1.8)
                .frame(width: 24, height: 24)
        case .upcoming:
            Circle()
                .stroke(statusTint.opacity(0.6), lineWidth: 1.5)
                .frame(width: 24, height: 24)
        }
    }

    private var statusControlLabel: String {
        switch item.status {
        case .done:     return "Mark as not done"
        case .skipped:  return "Un-skip"
        case .active, .due, .upcoming: return "Mark as done"
        }
    }
}

